mapper.select:
SELECT g.id, g.name, g.price, g.detail_info, g.images, g.type, g.reject_reason, g.sale_status, g.audit_status, g.user_id, g.create_time, g.update_time,
u.username, u.avatar_url
FROM goods g LEFT JOIN user u ON g.user_id = u.id WHERE g.id = #{id}

mapper.update:
UPDATE goods
SET audit_status = 1, sale_status = 1
WHERE id = #{id}

UPDATE goods
SET audit_status = 2, reject_reason = #{rejectReason}
WHERE id = #{id}

UPDATE goods
SET sale_status = #{saleStatus}
WHERE id = #{id}

mapper.select:
SELECT * FROM goods
WHERE user_id = #{id}
ORDER BY create_time DESC
